function startConditionSlideProgress(duration){const progress=$('#conditionSlideProgress'),fill=progress.querySelector('.condition-slide-progress-fill');progress.classList.remove('hidden','running');progress.style.setProperty('--slide-duration',`${duration}ms`);fill.style.animation='none';void fill.offsetWidth;fill.style.animation='';progress.classList.add('running')}
function clearConditionSlideProgress(){const progress=$('#conditionSlideProgress'),fill=progress.querySelector('.condition-slide-progress-fill');progress.classList.remove('running');progress.classList.add('hidden');fill.style.animation='none'}
function beginConditionSlides(selectedGroup){clearTimeout(conditionSlideHandle);conditionSlideHandle=null;clearConditionSlideProgress();conditionSlideIndex=0;conditionSlidePurpose='start-intro';conditionSlideSet=(CONDITION_GUIDE_SLIDES[selectedGroup]||CONDITION_GUIDE_SLIDES['green-green']).slice(0,2);$('#conditionSlides').dataset.condition=selectedGroup;$('#conditionSlides').classList.remove('level-story-overlay');$('#conditionSlides .guide-actions').classList.remove('hidden');updateConditionSlide();$('#setup').classList.add('hidden');$('#conditionSlides').classList.remove('hidden')}
function levelStorySlideNumber(mainIndex){return mainIndex<5?1:mainIndex-3}
function storySlidePath(mainIndex){const group=studyGroupId(),dir=CONDITION_STORY_DIRS[group]||CONDITION_STORY_DIRS['green-green'];return `assets/condition-stories/${dir}/${levelStorySlideNumber(mainIndex)}.gif`}
function beginFirstLevelStorySlides(){clearTimeout(conditionSlideHandle);conditionSlideHandle=null;conditionSlideIndex=0;conditionSlidePurpose='first-level';conditionSlideSet=[storySlidePath(0),PUZZLE_START_SLIDES[studyGroupId()]||PUZZLE_START_SLIDES['green-green']];$('#conditionSlides').dataset.condition=studyGroupId();$('#conditionSlides').classList.add('level-story-overlay');$('#conditionSlides .guide-actions').classList.add('hidden');updateConditionSlide();$('#conditionSlides').classList.remove('hidden');startConditionSlideProgress(10000);conditionSlideHandle=setTimeout(advanceLevelStorySlide,10000)}
function beginLevelStorySlides(level){clearBonusIntro();clearTimeout(conditionSlideHandle);conditionSlideHandle=null;conditionSlideIndex=0;conditionSlidePurpose='level';pendingCompletedLevel=level;conditionSlideSet=[storySlidePath(levelIndex),PUZZLE_START_SLIDES[studyGroupId()]||PUZZLE_START_SLIDES['green-green']];$('#conditionSlides').dataset.condition=studyGroupId();$('#conditionSlides').classList.add('level-story-overlay');$('#conditionSlides .guide-actions').classList.add('hidden');updateConditionSlide();$('#conditionSlides').classList.remove('hidden');startConditionSlideProgress(10000);conditionSlideHandle=setTimeout(advanceLevelStorySlide,10000)}
function advanceLevelStorySlide(){if(!['level','first-level'].includes(conditionSlidePurpose))return;if(conditionSlideIndex<conditionSlideSet.length-1){conditionSlideIndex++;updateConditionSlide();startConditionSlideProgress(5000);conditionSlideHandle=setTimeout(conditionSlidePurpose==='first-level'?finishFirstLevelStorySlides:finishLevelStorySlides,5000);return}if(conditionSlidePurpose==='first-level')finishFirstLevelStorySlides();else finishLevelStorySlides()}
function finishFirstLevelStorySlides(){clearTimeout(conditionSlideHandle);conditionSlideHandle=null;clearConditionSlideProgress();$('#conditionSlides').classList.add('hidden');$('#conditionSlides').classList.remove('level-story-overlay');$('#conditionSlides .guide-actions').classList.remove('hidden');conditionSlidesPassed=true;start()}
function finishLevelStorySlides(){clearTimeout(conditionSlideHandle);conditionSlideHandle=null;clearConditionSlideProgress();$('#conditionSlides').classList.add('hidden');$('#conditionSlides').classList.remove('level-story-overlay');$('#conditionSlides .guide-actions').classList.remove('hidden');pendingCompletedLevel=null;completionTransitionActive=false;levelRendered=false;render()}
function updateConditionSlide(){const set=conditionSlideSet,image=$('#conditionGuideImage');image.src=set[conditionSlideIndex];const storyType=$('#conditionSlides').dataset.condition.split('-')[1];image.alt=`${storyType==='green'?'Green':'City'} story, slide ${conditionSlideIndex+1} of ${set.length}`;$('#conditionSlideCount').textContent=`Slide ${conditionSlideIndex+1} of ${set.length}`;$('#nextConditionSlide').textContent=conditionSlideIndex<set.length-1?'Next':conditionSlidePurpose==='level'?'Next stop':conditionSlidePurpose==='start-intro'?'Continue':'Start game'}
function previousConditionSlide(){slideEffect();if(conditionSlidePurpose!=='start-intro')return;if(conditionSlideIndex>0){conditionSlideIndex--;updateConditionSlide();return}$('#conditionSlides').classList.add('hidden');$('#setup').classList.remove('hidden')}
function nextConditionSlide(){slideEffect();if(conditionSlidePurpose!=='start-intro')return;if(conditionSlideIndex<conditionSlideSet.length-1){conditionSlideIndex++;updateConditionSlide();return}beginFirstLevelStorySlides()}
function updateGuideSlide(){const image=$('#guideImage');image.src=GUIDE_SLIDES[guideSlideIndex];$('#slideCount').textContent=`Slide ${guideSlideIndex+1} of ${GUIDE_SLIDES.length}`;$('#nextGuideSlide').textContent=guideSlideIndex===GUIDE_SLIDES.length-1?'Start practice rounds':'Next'}
function previousGuideSlide(){slideEffect();if(guideSlideIndex>0){guideSlideIndex--;updateGuideSlide();return}$('#guideSlides').classList.add('hidden');$('#consentPage').classList.remove('hidden')}
function nextGuideSlide(){slideEffect();if(guideSlideIndex<GUIDE_SLIDES.length-1){guideSlideIndex++;updateGuideSlide();return}$('#guideSlides').classList.add('hidden');practiceIndex=0;renderPractice();$('#practiceScreen').classList.remove('hidden')}
function renderPractice(){clearTimeout(practiceSuccessHandle);practiceSuccessHandle=null;const level=PRACTICE_LEVELS[practiceIndex],grid=$('#practiceGrid');practiceVisited=[];practiceActive=false;practiceComplete=false;grid.innerHTML='';grid.style.gridTemplateColumns=`repeat(${level.width},minmax(0,1fr))`;$('#practiceCount').textContent=`PRACTICE ${practiceIndex+1} OF ${PRACTICE_LEVELS.length}`;$('#practiceProgress').textContent=`0 / ${level.path.length} squares`;$('#practiceHint').textContent='Touch S and drag through adjacent squares to E.';$('#practiceSuccess').classList.add('hidden');$('#practiceDecisionPrompt').classList.add('hidden');$('#practiceAgain').classList.add('hidden');$('#practiceNext').classList.toggle('hidden',practiceIndex!==0);$('#practiceNext').disabled=true;$('#practiceToSetup').classList.add('hidden');$('#practiceToSetup').disabled=true;for(let r=0;r<level.height;r++)for(let c=0;c<level.width;c++){const cell=document.createElement('div'),index=level.path.findIndex(([pr,pc])=>pr===r&&pc===c),kind=index===0?'S':index===level.path.length-1?'E':'#';cell.className='practice-tile'+(kind==='S'?' start':'')+(kind==='E'?' end':'');cell.dataset.practiceCell=key(r,c);cell.dataset.kind=kind;cell.textContent=kind==='S'?'S':kind==='E'?'E':'';cell.setAttribute('aria-label',kind==='S'?'Start square':kind==='E'?'End square':'Path square');grid.append(cell)}grid.onpointerdown=e=>{if(practiceComplete)return;const tile=e.target.closest('[data-practice-cell]');if(!tile)return;const id=tile.dataset.practiceCell,isStart=tile.dataset.kind==='S'&&practiceVisited.length===0,isResume=practiceVisited.length>0&&id===practiceVisited.at(-1);if(isStart||isResume){e.preventDefault();grid.setPointerCapture(e.pointerId);practiceActive=true;if(isStart){practiceVisited=[id];pianoTone(0);paintPractice()}}};grid.onpointermove=e=>{if(!practiceActive)return;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-practice-cell]');if(target)hitPractice(target)};grid.onpointerup=()=>{if(practiceActive){practiceActive=false;$('#practiceHint').textContent='Path paused. Touch the last square to continue, or Reset to try again.'}};paintPractice()}
function hitPractice(tile){if(!practiceActive||practiceComplete)return;const [r,c]=tile.dataset.practiceCell.split(',').map(Number),id=key(r,c),last=practiceVisited.at(-1),[lr,lc]=last.split(',').map(Number);if(id===last||practiceVisited.includes(id))return;if(Math.abs(r-lr)+Math.abs(c-lc)!==1)return;const level=PRACTICE_LEVELS[practiceIndex],isEnd=tile.dataset.kind==='E';if(isEnd&&practiceVisited.length!==level.path.length-1){practiceActive=false;$('#practiceHint').textContent='Visit every square before finishing at E. Reset and try again.';return}practiceVisited.push(id);pianoTone(practiceVisited.length-1);paintPractice();if(practiceVisited.length===level.path.length&&isEnd){practiceActive=false;practiceComplete=true;magicalSuccess();$('#practiceSuccess').classList.remove('hidden');$('#practiceHint').textContent=`Practice ${practiceIndex+1} complete.`;if(practiceIndex===PRACTICE_LEVELS.length-1){$('#practiceDecisionPrompt').classList.remove('hidden');$('#practiceAgain').classList.remove('hidden');$('#practiceToSetup').classList.remove('hidden');$('#practiceToSetup').disabled=false}else $('#practiceNext').disabled=false;practiceSuccessHandle=setTimeout(()=>{$('#practiceSuccess').classList.add('hidden');practiceSuccessHandle=null},5000)}}
function paintPractice(){$$('#practiceGrid .practice-tile').forEach(tile=>{tile.classList.toggle('visited',practiceVisited.includes(tile.dataset.practiceCell));tile.classList.toggle('current',tile.dataset.practiceCell===practiceVisited.at(-1))});$('#practiceProgress').textContent=`${practiceVisited.length} / ${PRACTICE_LEVELS[practiceIndex].path.length} squares`}
function resetPractice(){clearTimeout(practiceSuccessHandle);practiceSuccessHandle=null;practiceVisited=[];practiceActive=false;practiceComplete=false;$('#practiceSuccess').classList.add('hidden');$('#practiceDecisionPrompt').classList.add('hidden');$('#practiceAgain').classList.add('hidden');$('#practiceToSetup').classList.add('hidden');$('#practiceHint').textContent='Touch S and drag through adjacent squares to E.';$('#practiceNext').classList.toggle('hidden',practiceIndex!==0);$('#practiceNext').disabled=true;paintPractice()}
$('#previousConditionSlide').addEventListener('click',previousConditionSlide);$('#nextConditionSlide').addEventListener('click',nextConditionSlide);$('#previousGuideSlide').addEventListener('click',previousGuideSlide);$('#nextGuideSlide').addEventListener('click',nextGuideSlide);$('#practiceAgain').addEventListener('click',()=>{practiceIndex=0;renderPractice()});$('#practiceReset').addEventListener('click',resetPractice);$('#practiceNext').addEventListener('click',()=>{if(!practiceComplete||practiceIndex!==0)return;practiceIndex=1;renderPractice()});$('#practiceToSetup').addEventListener('click',()=>{if(!practiceComplete)return;$('#practiceScreen').classList.add('hidden');setup.classList.remove('hidden')});
